    82→/* ============================================
    83→   DARK FIRST DESIGN SYSTEM - ChooseWisely
    84→   ============================================ */
    85→
    86→:root {
    87→  /* Brand Colors - Dark First */
    88→  --brand-deep: #050810;
    89→  --brand-surface: #0d121f;
    90→  --brand-elevated: #141b2d;
    91→  --brand-accent: #34d399;
    92→  --brand-highlight: #6366f1;
    93→  --brand-danger: #f43f5e;
    94→
    95→  /* Text Colors */
    96→  --text-primary: #f8fafc;
    97→  --text-secondary: #94a3b8;
    98→  --text-muted: #64748b;
    99→
   100→  /* Effects */
   101→  --border-subtle: rgba(255, 255, 255, 0.06);
   102→  --border-glass: rgba(255, 255, 255, 0.1);
   103→  --glow-accent: rgba(52, 211, 153, 0.15);
   104→  --glow-accent-strong: rgba(52, 211, 153, 0.3);
   105→  --glow-highlight: rgba(99, 102, 241, 0.15);
   106→  --glow-highlight-strong: rgba(99, 102, 241, 0.3);
   107→
   108→  /* Glass morphism */
   109→  --glass-bg: rgba(255, 255, 255, 0.03);
   110→  --glass-bg-elevated: rgba(255, 255, 255, 0.05);
   111→  --glass-border: rgba(255, 255, 255, 0.06);
   112→
   113→  /* Dark First Colors (applied by default) */
   114→  --background: var(--brand-deep);
   115→  --foreground: var(--text-primary);
   116→  --card: var(--brand-surface);
   117→  --card-foreground: var(--text-primary);
   118→  --popover: var(--brand-surface);
   119→  --popover-foreground: var(--text-primary);
   120→  --primary: var(--brand-accent);
   121→  --primary-foreground: var(--brand-deep);
   122→  --secondary: var(--brand-elevated);
   123→  --secondary-foreground: var(--text-primary);
   124→  --muted: var(--brand-elevated);
   125→  --muted-foreground: var(--text-muted);
   126→  --accent: var(--brand-highlight);
   127→  --accent-foreground: var(--text-primary);
   128→  --destructive: var(--brand-danger);
   129→  --destructive-foreground: var(--text-primary);
   130→  --border: var(--border-subtle);
   131→  --input: var(--border-subtle);
   132→  --ring: var(--brand-accent);
   133→
   134→  /* Chart colors */
   135→  --chart-1: var(--brand-accent);
   136→  --chart-2: var(--brand-highlight);
   137→  --chart-3: #a78bfa;
   138→  --chart-4: #f472b6;
   139→  --chart-5: #fbbf24;
   140→
   141→  --radius: 0.75rem;
   142→
   143→  /* Sidebar */
   144→  --sidebar: var(--brand-surface);
   145→  --sidebar-foreground: var(--text-primary);
   146→  --sidebar-primary: var(--brand-accent);
   147→  --sidebar-primary-foreground: var(--brand-deep);
   148→  --sidebar-accent: var(--brand-elevated);
   149→  --sidebar-accent-foreground: var(--text-primary);
   150→  --sidebar-border: var(--border-subtle);
   151→  --sidebar-ring: var(--brand-accent);
   152→
   153→  /* Status colors */
   154→  --success: #34d399;
   155→  --success-foreground: var(--brand-deep);
   156→
   157→  --warning: #fbbf24;
   158→  --warning-foreground: var(--brand-deep);
   159→
   160→  --info: var(--brand-highlight);
   161→  --info-foreground: var(--text-primary);
   162→}
   163→
   164→/* Dark mode (default, reinforced) */
   165→.dark {
   166→  --background: var(--brand-deep);
   167→  --foreground: var(--text-primary);
   168→  --card: var(--brand-surface);
   169→  --card-foreground: var(--text-primary);
   170→  --popover: var(--brand-surface);
   171→  --popover-foreground: var(--text-primary);
   172→  --primary: var(--brand-accent);
   173→  --primary-foreground: var(--brand-deep);
   174→  --secondary: var(--brand-elevated);
   175→  --secondary-foreground: var(--text-primary);
   176→  --muted: var(--brand-elevated);
   177→  --muted-foreground: var(--text-muted);
   178→  --accent: var(--brand-highlight);
   179→  --accent-foreground: var(--text-primary);
   180→  --destructive: var(--brand-danger);
   181→  --destructive-foreground: var(--text-primary);
   182→  --border: var(--border-subtle);
   183→  --input: var(--border-subtle);
   184→  --ring: var(--brand-accent);
   185→  --sidebar: var(--brand-surface);
   186→  --sidebar-foreground: var(--text-primary);
   187→  --sidebar-primary: var(--brand-accent);
   188→  --sidebar-primary-foreground: var(--brand-deep);
   189→  --sidebar-accent: var(--brand-elevated);
   190→  --sidebar-accent-foreground: var(--text-primary);
   191→  --sidebar-border: var(--border-subtle);
   192→  --sidebar-ring: var(--brand-accent);
   193→}
